window.kbPageData["views/entry/k-1618e297e971dc67"] = {"key":"entry/k-1618e297e971dc67","state":{"route":"entry/k-1618e297e971dc67"},"node":{"id":"k-1618e297e971dc67","mode":"k","title":"必要条件","type":"概念与词义","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["必要条件的定义"],"qs":["国考 2023 副省级 行测#114"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"如果某个结果成立时某项条件必须满足，该条件就是这个结果的必要条件。缺少必要条件，结果便不能成立。","review":{"definition":"如果某个结果成立时某项条件必须满足，该条件就是这个结果的必要条件。缺少必要条件，结果便不能成立。","explanation":"“只有P，才Q”表示Q成立必有P。题干把围绕市场主体需求实施更大力度减税降费列为帮助其渡过资金难关所必需的举措，A项保留了这个方向。按题干的逻辑，B项仅凭稳住市场主体就断定经济能够稳中求进，C项仅凭深化“放管服”改革就断定可以改善营商环境，都把所需条件当成了结果成立的保证。D项则把内生动力有助于进一步增强经济吸引力、创造力和竞争力，说成缺少内生动力时这些能力完全不存在，超出了题干表述。","references":[],"evidence":"只有围绕市场主体需求实施更大力度减税降费，才能帮助其渡过资金难关。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#114":{"paper":"国考 2023 副省级 行测","n":114,"mod":"判断推理","src":["503793642e845de9795f.pdf",23],"asrc":["ecade1ff5af69283232e.pdf",36],"card":"5b841e21b9351e5a95087c30","links":[{"id":"k-1618e297e971dc67","role":"解题依据","why":"必要条件须在结果成立时满足，因而位于结果所蕴含的一侧。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-1618e297e971dc67":[["国考 2023 副省级 行测#114"]]}};
